SELECT qryElektrolyseureInTeilanlage.Teilanlagenbezeichnung, qryCEAlleElektrolyseure.Datum, qryCEAlleElektrolyseure.Zeit, Avg(qryCEAlleElektrolyseure.[µNaOH]) AS [Mittelwert von µNaOH], Sum(qryCEAlleElektrolyseure.VAnolyt) AS [Summe von VAnolyt], Avg(qryCEAlleElektrolyseure.ConcCl2) AS [Mittelwert von ConcCl2], Avg(qryCEAlleElektrolyseure.ConcO2) AS [Mittelwert von ConcO2], Avg(qryCEAlleElektrolyseure.[µNaClO3]) AS [Mittelwert von µNaClO3], Avg(qryCEAlleElektrolyseure.[µNaOCl]) AS [Mittelwert von µNaOCl], Avg(qryCEAlleElektrolyseure.[µAlkali]) AS [Mittelwert von µAlkali], Avg(qryCEAlleElektrolyseure.[µNa2CO3]) AS [Mittelwert von µNa2CO3], Avg(qryCEAlleElektrolyseure.[µHCl]) AS [Mittelwert von µHCl], Avg(qryCEAlleElektrolyseure.[µO2]) AS [Mittelwert von µO2]
FROM qryElektrolyseureInTeilanlage INNER JOIN qryCEAlleElektrolyseure ON qryElektrolyseureInTeilanlage.Elektrolyseurbezeichnung = qryCEAlleElektrolyseure.Elektrolyseur
GROUP BY qryElektrolyseureInTeilanlage.Teilanlagenbezeichnung, qryCEAlleElektrolyseure.Datum, qryCEAlleElektrolyseure.Zeit;
